       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_15_v1'
from (values
('127.99.d.1.A',3,'A client needs a garage that fits two trucks and a workbench. Which design step comes first?','["Listing the space and function requirements", "Ordering shingles", "Painting the walls", "Hanging doors"]'::jsonb,0,'Design starts from the stated need.','original'),
('127.99.d.1.A',4,'A designer reworks a floor plan after the client asks for wider hallways. This is an example of:','["Starting over without a goal", "Improving a design to meet a changed need", "Ignoring the client", "Skipping the plan"]'::jsonb,1,'Revisions respond to specified needs.','original'),
('127.99.d.1.B',3,'Sketching several layouts before choosing one helps a design team to:','["Skip approvals", "Avoid all decisions", "Compare ideas and communicate options", "Hide the plan"]'::jsonb,2,'Alternatives make choices clearer.','original'),
('127.99.d.1.B',4,'A design team shows a client a 3D rendering mainly to:','["Replace the building permit", "Pay the crew", "Order lumber", "Communicate how the finished building will look"]'::jsonb,3,'Visuals convey design intent.','original'),
('127.99.d.2.A',3,'A student reporting on emerging construction technology could cover:','["Drone site surveys", "Horse-drawn mixers", "Oil lamps", "Hand-carved lintels"]'::jsonb,0,'Drones are a current technology.','original'),
('127.99.d.2.A',4,'Prefabricated modular homes are an emerging approach because they:','["Never need inspection", "Move much of the building process into a factory", "Are built only by hand on site", "Eliminate all materials"]'::jsonb,1,'Factory work saves time and waste.','original'),
('127.99.d.2.B',3,'A good research question for a materials study is:','["Which color is prettiest?", "What is for lunch?", "Which insulation lowers heat loss the most?", "Who is tallest?"]'::jsonb,2,'Testable questions guide research.','original'),
('127.99.d.2.B',4,'To make a comparison of two sealants fair, the researcher should:','["Skip measuring", "Use different amounts", "Test one indoors and one in rain", "Test them under the same conditions"]'::jsonb,3,'Controls make results valid.','original'),
('127.99.d.3.A',3,'A quality benchmark for a framed wall might be that studs are:','["Within a set tolerance of plumb", "Unfastened", "Different lengths", "Any angle"]'::jsonb,0,'Specified quality uses measurable limits.','original'),
('127.99.d.3.A',4,'Building a birdhouse to a written tolerance of 1/16 inch requires:','["No layout marks", "Accurate measuring and careful cutting", "Quick guesses", "Dull blades"]'::jsonb,1,'Tolerance demands precision.','original'),
('127.99.d.3.B',3,'A recommendation to improve building quality could be to:','["Stop inspections", "Use damaged lumber", "Add a mid-job inspection checklist", "Skip curing time"]'::jsonb,2,'Checklists catch errors early.','original'),
('127.99.d.3.B',4,'Switching to better flashing details after leak complaints would improve:','["Paint color", "Lawn growth", "Parking space", "Durability of the building envelope"]'::jsonb,3,'Details control water entry.','original'),
('127.99.d.3.C',3,'Which factor most affects the quality of a finished building?','["Skill of workers and quality of materials", "Day of the week", "The brand of the owner''s car", "The foreman''s lunch"]'::jsonb,0,'Workmanship and materials set quality.','original'),
('127.99.d.3.C',4,'Rushing concrete curing to save a day can lower quality because it may:','["Improve color", "Reduce final strength", "Save water forever", "Increase strength"]'::jsonb,1,'Proper curing builds strength.','original'),
('127.99.d.3.D',3,'A buyer comparing two houses most likely weighs price against:','["Weather in another state", "The mailbox color", "Location, size, and condition", "The builder''s nickname"]'::jsonb,2,'Buying decisions weigh features.','original'),
('127.99.d.3.D',4,'Energy-efficiency ratings affect purchase decisions because they predict:','["Neighborhood noise", "Tree height", "Tax forms", "Long-term utility costs"]'::jsonb,3,'Efficiency lowers operating cost.','original'),
('127.99.d.4.A',3,'Concrete''s high compressive strength is an example of a:','["Mechanical property", "Legal rule", "Chemical hobby", "Social trend"]'::jsonb,0,'Strength is a mechanical property.','original'),
('127.99.d.4.A',4,'An ASTM standard for a building material specifies:','["Owner''s preferences", "Test methods and minimum requirements", "Delivery tips", "Color names"]'::jsonb,1,'Standards set measurable limits.','original'),
('127.99.d.4.B',3,'Pouring, finishing, and curing are processes used to place:','["Lumber", "Carpet", "Concrete", "Glass"]'::jsonb,2,'These are concrete placement steps.','original'),
('127.99.d.4.B',4,'In construction, ''sequencing'' of processes means:','["Skipping steps", "Doing tasks randomly", "Duplicating work", "Putting tasks in the order they must occur"]'::jsonb,3,'Order prevents rework.','original'),
('127.99.d.4.C',3,'A student building a scale model of a bridge must choose tools and:','["Materials suited to the model", "Unsafe methods", "No plan", "A random shape"]'::jsonb,0,'Tools and materials are matched to the task.','original'),
('127.99.d.4.C',4,'Selecting a coping saw to cut a curved trim piece shows matching:','["The shop to the street", "The tool to the task", "The nail to the tile", "The color to the room"]'::jsonb,1,'Tool choice affects results.','original'),
('127.99.d.5.A',3,'Before running a table saw, a student must show mastery of its:','["Menu", "Paint chart", "Safety test", "Parking rules"]'::jsonb,2,'Safety tests come before tool use.','original'),
('127.99.d.5.A',4,'A student who fails a power-tool safety test should:','["Skip the test", "Ask a friend to use it", "Use the tool anyway", "Review the material and retake it before using the tool"]'::jsonb,3,'Mastery is required.','original'),
('127.99.d.5.B',3,'A safety data sheet is part of the safety documents that tell workers how to:','["Handle a chemical safely", "Pay taxes", "Choose paint colors", "Order lunch"]'::jsonb,0,'SDS explain hazards.','original'),
('127.99.d.5.B',4,'Following the manufacturer''s instructions for a nail gun includes:','["Bypassing the contact tip", "Wearing eye protection and keeping fingers off the trigger until ready", "Removing the safety", "Pointing it at coworkers"]'::jsonb,1,'Instructions prevent injury.','original'),
('127.99.d.5.C',3,'Oil-based stains and thinners are classified as:','["Clean water", "Dry sand", "Hazardous materials", "Food items"]'::jsonb,2,'Chemical products can be hazardous.','original'),
('127.99.d.5.C',4,'Wood treated with certain preservatives may be classified as hazardous waste when:','["It is measured", "It is used as designed", "It is stacked", "It is discarded in some forms"]'::jsonb,3,'Disposal rules can apply.','original'),
('127.99.d.5.D',3,'Disposing of leftover stain properly means:','["Following local waste rules and using approved containers", "Pouring it outside", "Hiding it in trash", "Burning it"]'::jsonb,0,'Proper disposal protects the environment.','original'),
('127.99.d.5.D',4,'Used solvent-soaked rags can ignite spontaneously, so they are:','["Piled in a corner", "Kept in a metal container with a lid", "Stored in a paper bag", "Left in sunlight"]'::jsonb,1,'Containment prevents fires.','original'),
('127.99.d.5.E',3,'A crew recommends adding a second guard on a saw after a near miss. This is a:','["Color change", "Schedule delay only", "Safety procedure improvement", "Cost increase only"]'::jsonb,2,'Near misses prompt improvements.','original'),
('127.99.d.5.E',4,'Reporting a hazard to a supervisor helps improve:','["Nothing", "Only the supervisor", "Only the report", "The safety of everyone on the site"]'::jsonb,3,'Reporting leads to fixes.','original'),
('127.99.d.6.A',3,'A good habit for storing hand planes is to:','["Keep them clean, dry, and with blades retracted", "Throw them in a bin", "Rest them on blades", "Leave them in rain"]'::jsonb,0,'Careful storage prevents damage.','original'),
('127.99.d.6.A',4,'Sharpening chisels regularly makes work safer because sharp tools:','["Need more force", "Cut with less force and slip less", "Are noisy", "Break more often"]'::jsonb,1,'Sharp edges are more controllable.','original'),
('127.99.d.6.B',3,'A manufacturer''s maintenance schedule for a compressor might require:','["Painting the tank", "Unplugging gauges", "Draining moisture from the tank", "Adding sand"]'::jsonb,2,'Draining prevents rust.','original'),
('127.99.d.6.B',4,'Lubricating a drill press as the maker recommends helps it:','["Stall", "Vibrate", "Run dry", "Run smoothly and last longer"]'::jsonb,3,'Lubrication reduces wear.','original'),
('127.99.d.6.C',3,'A maintenance plan lists tasks, schedules, and:','["Who is responsible", "Weather", "Lunch orders", "Wall colors"]'::jsonb,0,'Plans assign responsibility.','original'),
('127.99.d.6.C',4,'Tracking blade changes and cleanings in a log lets a shop:','["Hide problems", "Plan service before failures occur", "Order unrelated parts", "Skip repairs"]'::jsonb,1,'Logs support preventive maintenance.','original'),
('127.99.d.7.A',3,'Starting a construction project usually begins with:','["Hanging pictures", "Ordering a dumpster", "Defining the scope and goals", "Cleaning tools"]'::jsonb,2,'Initiation defines what is to be built.','original'),
('127.99.d.7.A',4,'A project charter is created to:','["Pick paint", "Hire janitors", "Pour the slab", "Authorize the project and state its objectives"]'::jsonb,3,'A charter formalizes the start.','original'),
('127.99.d.7.B',3,'A project plan commonly includes a:','["Schedule, budget, and resource list", "Playlist", "Photo album", "Joke book"]'::jsonb,0,'Plans organize the work.','original'),
('127.99.d.7.B',4,'Breaking a project into smaller tasks is called creating a:','["Punch list", "Work breakdown structure", "Roof truss", "Site plan"]'::jsonb,1,'WBS divides work into manageable parts.','original'),
('127.99.d.7.C',3,'During execution of a project, the crew:','["Cancels the plan", "Revises the goals", "Carries out the planned work", "Writes the final report only"]'::jsonb,2,'Execution is where work is done.','original'),
('127.99.d.7.C',4,'Daily huddles during execution help the team to:','["Add risk", "Delay work", "Reduce communication", "Coordinate tasks and spot problems"]'::jsonb,3,'Short check-ins keep the work aligned.','original'),
('127.99.d.7.D',3,'Comparing actual progress to the schedule is part of:','["Monitoring and controlling", "Closing", "Marketing", "Initiating"]'::jsonb,0,'Monitoring tracks performance.','original'),
('127.99.d.7.D',4,'If a project falls behind schedule, the manager should:','["Ignore it", "Identify the cause and adjust the plan", "Blame workers", "Stop the project"]'::jsonb,1,'Control means correcting course.','original'),
('127.99.d.7.E',3,'Closing a project includes a final inspection and:','["Starting a new plan", "Ordering more lumber", "Handing over the finished work", "Ignoring leftovers"]'::jsonb,2,'Closing delivers results.','original'),
('127.99.d.7.E',4,'A lessons-learned review at closing helps future projects by:','["Avoiding feedback", "Hiding mistakes", "Skipping records", "Capturing what worked and what did not"]'::jsonb,3,'Reviews improve future work.','original'),
('127.99.d.8.A',3,'Electrical, plumbing, and fire safety are areas where a builder may need to follow:','["Codes and regulations", "Fashion trends", "Recipes", "Sports rules"]'::jsonb,0,'Codes cover trades.','original'),
('127.99.d.8.A',4,'Accessibility requirements for entrances come from:','["Neighbors", "Laws such as the ADA and building codes", "Delivery drivers", "Paint companies"]'::jsonb,1,'Accessibility is regulated.','original'),
('127.99.d.8.B',3,'A builder finds the local building code by checking with the:','["Local bakery", "Radio station", "City or county building department", "Gas station"]'::jsonb,2,'Local offices adopt codes.','original'),
('127.99.d.8.B',4,'International model codes are often adopted by local governments with:','["Random edits", "No changes ever", "Ignored provisions", "Amendments"]'::jsonb,3,'Local amendments may apply.','original'),
('127.99.d.8.C',3,'A contractor demonstrates code compliance through:','["Permits and inspections", "Photos of lunch", "Verbal promises", "A signed joke"]'::jsonb,0,'Inspections verify compliance.','original'),
('127.99.d.8.C',4,'If an inspector flags a violation, the builder should:','["Ignore it", "Correct it and request reinspection", "Hide it", "Argue and stop work"]'::jsonb,1,'Corrections are required.','original'),
('127.99.d.9.A',3,'A first step in a problem-solving process for a leaking roof valley is to:','["Ignore it", "Paint the ceiling", "Define and investigate the problem", "Replace the whole roof"]'::jsonb,2,'Understand before acting.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
